            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0xEA47AF66FD06E1ADULL) + aOrbiterUpdateSaltC[((aIndex + 6U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xC193635C7172CE6DULL;
