            aWandererJ = aWandererJ + ((RotL64(aIngress, 39U) + aOrbiterD) + RotL64(aOrbiterF, 27U));
            aWandererB = aWandererB ^ (((RotL64(aCross, 41U) + RotL64(aOrbiterG, 35U)) + aOrbiterF) + aPhaseAWandererUpdateSaltA[((aIndex + 10U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aScatter, 3U) + RotL64(aOrbiterJ, 43U)) + aOrbiterK);
            aWandererG = aWandererG ^ (((RotL64(aPrevious, 51U) + RotL64(aOrbiterK, 41U)) + aOrbiterG) + aPhaseAWandererUpdateSaltB[((aIndex + 29U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aScatter, 19U) + RotL64(aOrbiterK, 3U)) + aOrbiterH) + aNonceWordP);
            aWandererI = aWandererI ^ ((RotL64(aCross, 54U) + aOrbiterJ) + RotL64(aOrbiterE, 5U));
            aWandererF = aWandererF + ((RotL64(aPrevious, 43U) + aOrbiterI) + RotL64(aOrbiterG, 24U));
            //
