            //
            aIngress = (RotL64(aWaterLaneC[((aIndex + 30699U)) & S_BLOCK1], 39U) ^ RotL64(aWaterLaneA[((aIndex + 27413U)) & S_BLOCK1], 47U));
            aIngress ^= RotL64(aEarthLaneD[((aIndex + 29922U)) & S_BLOCK1], 13U);
