            aOrbiterD = (aWandererH + RotL64(aPrevious, 23U)) + 0x17CA1C0623C31F47ULL;
            aOrbiterA = (aWandererK + RotL64(aScatter, 38U)) + 0xCE60B783DD8EC456ULL;
            aOrbiterB = (aWandererJ + RotL64(aIngress, 57U)) + 0x138A1B8902C624BEULL;
