            aOrbiterG = ((aWandererA + RotL64(aCross, 13U)) + RotL64(aCarry, 47U)) + 0x62BAF2512C2502B9ULL;
            aOrbiterC = (((aWandererF + RotL64(aScatter, 60U)) + RotL64(aCarry, 41U)) + 0x5A6302A9C8B42225ULL) + aNonceWordA;
