            aOrbiterK = ((aOrbiterK + aOrbiterE) + 0x9F19988280E755F7ULL) + aPhaseBOrbiterUpdateSaltB[((aIndex + 6U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x4C4FB708BA4C530BULL;
            aOrbiterF = RotL64((aOrbiterF * 0xD92926DA9550AFE5ULL), 23U);
