            aOrbiterK = RotL64((aOrbiterK * 0xED274DA5F2559169ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0xB1873AD52FB3CBD2ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0xADD8DA7F765EC56DULL;
            aOrbiterI = RotL64((aOrbiterI * 0x021EF589534A6581ULL), 39U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x8BFBB34CA0551AC6ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xF59DFA859BB794A3ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xDA72EA1B02A9010FULL), 27U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0xD82B0E8F468AD5D3ULL;
