            //
            aOrbiterB = ((aOrbiterB + aOrbiterG) + 0x0D68482A1CB3D538ULL) + aPhaseBOrbiterUpdateSaltE[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterD = (((aOrbiterD ^ aOrbiterB) ^ 0x4DC20C4234D1628EULL) ^ aPhaseBOrbiterUpdateSaltD[((aIndex + 28U)) & S_SALT1]) ^ aNonceWordN;
