            //
            aWandererB = aWandererB + ((((RotL64(aPrevious, 29U) + aOrbiterC) + RotL64(aOrbiterH, 54U)) + RotL64(aCarry, 51U)) + aNonceWordJ);
            aWandererC = aWandererC ^ (((RotL64(aCross, 37U) + aOrbiterI) + RotL64(aOrbiterA, 47U)) + aPhaseDWandererUpdateSaltA[(((31U - aIndex) + 18U)) & S_SALT1]);
