            aIngress = (RotL64(aHeartLaneA[((aIndex + 6002U)) & S_BLOCK1], 60U) ^ RotL64(aHeartLaneB[((aIndex + 976U)) & S_BLOCK1], 13U));
            aIngress ^= (RotL64(aFireLaneC[((aIndex + 1295U)) & S_BLOCK1], 35U) ^ RotL64(aWaterLaneB[((aIndex + 1712U)) & S_BLOCK1], 47U));
