            aCross = (RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 5724U)) & S_BLOCK1], 21U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 4955U)) & S_BLOCK1], 29U));
