            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aIngress, 10U) + RotL64(aCarry, 27U)) ^ (RotL64(aCross, 39U) + RotL64(aPrevious, 57U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterF = ((aWandererD + RotL64(aPrevious, 13U)) + 0xFDB3A910E47695CCULL) + aPhaseCOrbiterAssignSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterJ = (aWandererK + RotL64(aIngress, 43U)) + 0x7D14B3739A7EF177ULL;
            aOrbiterE = (aWandererH + RotL64(aScatter, 53U)) + 0xE3F6C3F296A277E2ULL;
            aOrbiterC = ((aWandererC + RotL64(aCross, 29U)) + 0x8DBE54E1CAEB1691ULL) + aPhaseCOrbiterAssignSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterA = ((aWandererA + RotL64(aScatter, 20U)) + RotL64(aCarry, 41U)) + 0x7AE61AD30A8C43C2ULL;
            aOrbiterD = ((aWandererB + RotL64(aIngress, 37U)) + RotL64(aCarry, 57U)) + 0xF0D8A54F30A8C36DULL;
            aOrbiterG = ((aWandererE + RotL64(aPrevious, 5U)) + RotL64(aCarry, 21U)) + 0x22330543BB2820AEULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0xD8AF30BA60F160F3ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x8A57CF99C4997532ULL) ^ aPhaseCOrbiterUpdateSaltE[((aIndex + 26U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xF51D815199B19799ULL), 41U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x5468CAB152F53B63ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x9D89694583A6F16AULL) ^ aPhaseCOrbiterUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x96F0C0D30F7BF3C9ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x637770986392D851ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x59104A16F5C28B87ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x3B6C3E58C81A2C9BULL), 47U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0x0D146630F39ED686ULL) + aPhaseCOrbiterUpdateSaltF[((aIndex + 23U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0xCBA775829EA10942ULL) ^ aPhaseCOrbiterUpdateSaltA[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xF957AC6566F72223ULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xFC7284C6DF0D3626ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x2E69DE5A8DF882E1ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x1EEA619099411AA7ULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x73534E3223DF5E9CULL;
