            aOrbiterG = RotL64((aOrbiterG * 0x8BAC63F6705419F5ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0xF440DD83AF8CEB32ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0xCD632B41AF0498A6ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB336499A82E75A49ULL), 57U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterE, 43U);
            aIngress = aIngress + (RotL64(aOrbiterD, 11U) ^ aOrbiterA);
            aIngress = aIngress + (RotL64(aOrbiterJ, 19U) ^ aOrbiterF);
