            aOrbiterG = ((aWandererK + RotL64(aIngress, 5U)) + RotL64(aCarry, 53U)) + 0xFC776C0CE05C0E5CULL;
            aOrbiterJ = ((aWandererF + RotL64(aScatter, 13U)) + 0xD783C19D30262F4DULL) + aPhaseDOrbiterAssignSaltD[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterE = (aWandererE + RotL64(aPrevious, 27U)) + 0x235FAAD728C37BF7ULL;
            aOrbiterI = (((aWandererB + RotL64(aCross, 47U)) + RotL64(aCarry, 41U)) + 0xEAB33205A42CC7C7ULL) + aPhaseDOrbiterAssignSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = (aWandererH + RotL64(aScatter, 39U)) + 0xF144AE087B537F48ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xD98A06F147AB8E04ULL;
