            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x1B07AEA47AF366A7ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x5B2926CC5D652B9EULL;
            aOrbiterA = RotL64((aOrbiterA * 0x8A40A548F7C52EE7ULL), 5U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterF) + 0x084542D9C1256891ULL) + aPhaseDOrbiterUpdateSaltD[((aIndex + 26U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0xF63549F80FDAB705ULL) ^ aPhaseDOrbiterUpdateSaltC[((aIndex + 21U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x84D409B95EBFA79DULL), 27U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterG) + 0x7E477D7BDEC90B2CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0xF2D478C91A9AE4F8ULL;
