            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0x8503811D1D7BF3D5ULL) + aPhaseDOrbiterUpdateSaltE[((aIndex + 15U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x5C3CFD073110A7A8ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x07C0C754D81C4271ULL), 35U);
            //
            aIngress = aOrbiterI ^ RotL64(aOrbiterH, 3U);
