            aOrbiterF = ((aWandererJ + RotL64(aIngress, 3U)) + 0x3CD08703E85B9433ULL) + aPhaseAOrbiterAssignSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aScatter, 19U)) + 0x114F35E18F76497BULL;
            aOrbiterD = ((aWandererK + RotL64(aCross, 56U)) + 0x29703DF473C21EBBULL) + aPhaseAOrbiterAssignSaltD[(((31U - aIndex) + 16U)) & S_SALT1];
