            aWandererC = aWandererC ^ (((RotL64(aPrevious, 29U) + aOrbiterH) + RotL64(aOrbiterI, 37U)) + aPhaseAWandererUpdateSaltA[((aIndex + 14U)) & S_SALT1]);
